const { withAppBuildGradle } = require('expo/config-plugins');

/**
 * Signs the Android release build with the StreetShelf upload keystore.
 *
 * `android/` is generated by `expo prebuild`, so the signing block cannot
 * live there. The path, alias and password come from the environment
 * (`scripts/release-android.sh` reads the password from the macOS Keychain);
 * without them the release variant keeps the debug key, so local release
 * builds still work and nothing secret is ever written to a file.
 */
module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    let gradle = cfg.modResults.contents;
    if (gradle.includes('STREETSHELF_KEYSTORE_PASSWORD')) return cfg;

    gradle = gradle.replace(
      /signingConfigs \{\s*debug \{[\s\S]*?\n        \}\n/,
      (debugBlock) =>
        `${debugBlock}        release {
            def storePath = System.getenv('STREETSHELF_KEYSTORE_PATH')
            if (storePath && System.getenv('STREETSHELF_KEYSTORE_PASSWORD')) {
                storeFile file(storePath)
                storePassword System.getenv('STREETSHELF_KEYSTORE_PASSWORD')
                keyAlias System.getenv('STREETSHELF_KEY_ALIAS') ?: 'streetshelf-upload'
                keyPassword System.getenv('STREETSHELF_KEYSTORE_PASSWORD')
            }
        }
`,
    );
    gradle = gradle.replace(
      /(buildTypes \{[\s\S]*?\n        release \{[\s\S]*?)signingConfig signingConfigs\.debug/,
      `$1signingConfig System.getenv('STREETSHELF_KEYSTORE_PASSWORD') ? signingConfigs.release : signingConfigs.debug`,
    );
    cfg.modResults.contents = gradle;
    return cfg;
  });
};
